settings.sectionCSS:
.aQZRjy p {
	color: [[${globalDesignMode ? 'var(--colorSecondary)' : colorSecondary}]];
	font-size: [[${globalDesignMode ? 'calc(var(--fontSizeBody) * 1px)' : fontSizeBody + 'px'}]];
}

.aQZRjy p + p {
	margin-top: 0.3125rem;
}

.aQZRjy .aQZRjy-list .embed-responsive {
	width: 9.375rem;
	margin-right: 0.9375rem;
}

.aQZRjy .aQZRjy-slick {
	position: relative;
}

.aQZRjy .aQZRjy-group {
	position: relative;
	width: 100%;
	left: 0;
	top: 0;
	opacity: 1;
}

.aQZRjy .aQZRjy-group:not(.active) {
	position: absolute;
	opacity: 0;
	z-index: 0;
}

.aQZRjy .aQZRjy-group.active {
	z-index: 1;
}

.aQZRjy .nav-pills .nav-link {
	transition: all 0.25s;
}

.aQZRjy .nav-pills .nav-link:hover:hover {
	background-color: [[${globalDesignMode ? 'var(--colorButtonHover)' : colorButtonHover}]];
	color: [[${globalDesignMode ? 'var(--colorButtonHoverLabel)' : colorButtonHoverLabel}]];
}
